import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written double for the downstream pricing service (unit price in euros).
const prices = { apple: 10, pear: 2.5, gold: 60, cent: 0.99 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body) })
const json = async (res) => [res.status, res.headers.get('content-type'), await res.json()]

test('POST /orders creates an order, no discount at or below 100', async () => {
  const [status, type, body] = await json(await post({ items: [{ sku: 'apple', qty: 10 }] }))
  assert.equal(status, 201)
  assert.equal(type, 'application/json')
  assert.match(body.id, /^\d+$/)
  assert.deepEqual(body.items, [{ sku: 'apple', qty: 10 }])
  assert.equal(body.total, 100)
})

test('POST /orders applies 10% discount above 100', async () => {
  const [status, , body] = await json(await post({ items: [{ sku: 'gold', qty: 2 }] }))
  assert.equal(status, 201)
  assert.equal(body.total, 108)
})

test('POST /orders truncates total to whole euros', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — total is Math.floor'ed, so cents are dropped (2.5 -> 2, not rounded)
  const [, , body] = await json(await post({ items: [{ sku: 'pear', qty: 1 }] }))
  assert.equal(body.total, 2)
  const [, , b2] = await json(await post({ items: [{ sku: 'cent', qty: 3 }] }))
  assert.equal(b2.total, 2)
})

test('POST /orders sums several items', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 4 }] }))
  assert.equal(body.total, 20)
})

test('POST /orders assigns increasing ids', async () => {
  const [, , a] = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  const [, , b] = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders with unknown sku or missing qty yields null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null with status 201
  const [status, , body] = await json(await post({ items: [{ sku: 'nope', qty: 1 }] }))
  assert.equal(status, 201)
  assert.equal(body.total, null)
  const [s2, , b2] = await json(await post({ items: [{ sku: 'apple' }] }))
  assert.equal(s2, 201)
  assert.equal(b2.total, null)
})

for (const [name, body, raw] of [
  ['empty body', undefined, ''],
  ['empty object', {}],
  ['empty items', { items: [] }],
  ['non-array items', { items: 'x' }],
  ['malformed JSON', undefined, '{oops'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const [status, type, out] = await json(await post(body, raw))
    assert.equal(status, 400)
    assert.equal(type, 'application/json')
    assert.deepEqual(out, { error: 'items required' })
  })
}

test('GET /orders/{id} returns a stored order', async () => {
  const [, , created] = await json(await post({ items: [{ sku: 'gold', qty: 2 }] }))
