  assert.deepEqual(body, created)
})

test('GET /orders/{id} for unknown id returns 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unknown order answers 200, not 404
  const [status, , body] = await json(await fetch(`${base}/orders/does-not-exist`))
